 "content": "def transform(grid):
    """Extend the center row and column of each solid 3x3 colored square."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[rr][cc] == color
                   for rr in range(r, r + 3)
                   for cc in range(c, c + 3)):
                # Only use a 3x3 square as a single source, not subwindows of a larger block.
                if r > 0 and all(grid[r - 1][cc] == color for cc in range(c, c + 3)):
                    continue
                if c > 0 and all(grid[rr][c - 1] == color for rr in range(r, r + 3)):
                    continue
                centers.append((r + 1, c + 1, color))
    rows, cols = {}, {}
    for r, c, color in centers:
        rows[r] = color
        cols[c] = color
    # Draw the source-colored lines, then erase any intersections between distinct lines.
    for r, color in rows.items():
        for c in range(w):
            out[r][c] = color
    for c, color in cols.items():
        for r in range(h):
            out[r][c] = color
    for r in rows:
        for c in cols:
            if rows[r] != cols[c]:
                out[r][c] = 0
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
